<?php

declare(strict_types=1);

namespace MintCart\Core;

/**
 * Loads the starter catalogue (`install/mintcart-demo.sql`, generated by
 * `scripts/demo/build_demo.py`) into a freshly installed store, so the store
 * opens with MintCart's own home-goods demo instead of OpenCart's.
 *
 * The file holds one statement per line and uses the stock `oc_` prefix; it
 * must run after the migrations (it fills the `mc_*` tables too). It replaces
 * the catalogue rows only - orders and customers are not touched.
 */
final class DemoData
{
    /**
     * @return int number of statements executed
     */
    public static function apply(object $db, string $prefix, string $file): int
    {
        if (!is_file($file)) {
            return 0;
        }

        $count = 0;

        foreach (file($file, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) ?: [] as $line) {
            $sql = trim($line);

            if ($sql === '') {
                continue;
            }

            $sql = preg_replace('/(?<![A-Za-z0-9_])oc_(?=[a-z])/', $prefix, $sql);

            $db->query($sql);
            $count++;
        }

        return $count;
    }
}
